import React, { useRef } from "react";

var arr = [
  {
    para1:
      "Design On A Dime has been an invaluable partner for RISE Worldwide, elevating our sports broadcast production with exceptional graphic solutions.",
    para2:
      "Their expertise and creativity have consistently enhanced our coverage of major football tournaments such as the Indian Super League, Intercontinental Cup, Super Cup, and many more, as well as bespoke cricket events like Indian Street Premier League - Season 1.",
    para3:
      "Collaborating with their team is always seamless, and their unwavering commitment to excellence truly sets them apart.",
    clientName: "James Rego",
    position: "Head - Broadcast and Production, Rise Worldwide",
  }
];

const Testimonials = () => {
  const testimonialRef = useRef(null);

  const scrollLeft = () => {
    testimonialRef.current.scrollBy({
      left: -testimonialRef.current.offsetWidth / 2, // Scroll by half the container's width to show 2 items at once
      behavior: "smooth",
    });
  };

  const scrollRight = () => {
    console.log(testimonialRef.current.offsetWidth-4);
    testimonialRef.current.scrollBy({
      left: testimonialRef.current.offsetWidth / 2, // Scroll by half the container's width to show 2 items at once
      behavior: "smooth",
    });
  };

  return (
    <section className="py-16 bg-primary-light">
      <div className="container mx-auto">
        <h2 className="font-Oswald text-3xl font-bold text-center mb-8 text-white">
          Testimonials
        </h2>
        <div className="relative">
          {/* Left Scroll Button */}
          <button
            onClick={scrollLeft}
            className="absolute left-0 top-1/2 transform -translate-y-1/2 bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-full shadow-md z-10"
          >
            &#8592;
          </button>

          {/* Testimonials Container */}
          <div
            ref={testimonialRef}
            className="flex items-center gap-1 justify-start overflow-hidden mx-auto max-w-[80%] transition duration-300"
          >
            {arr.map((testimonial, index) => (
              <div
                key={index}
                className="bg-gray-800 bg-opacity-50 p-4 shadow-md hover:bg-opacity-75 transition duration-300 w-[50%] flex-shrink-0"
              >
                <p className="text-gray-300">"{testimonial.para1}</p>
                <br />
                <p className="text-gray-300">{testimonial.para2}</p>
                <br />
                <p className="text-gray-300">"{testimonial.para3}"</p>
                <br />
                <h4 className="mt-4 font-bold text-white">
                  {testimonial.clientName}
                </h4>
                <p className="text-sm text-gray-400">{testimonial.position}</p>
              </div>
            ))}
          </div>

          {/* Right Scroll Button */}
          <button
            onClick={scrollRight}
            className="absolute right-0 top-1/2 transform -translate-y-1/2 bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-full shadow-md z-10"
          >
            &#8594;
          </button>
        </div>
      </div>
    </section>
  );
};

export default Testimonials;
